#!/usr/bin/env python3
"""Lab 2, Part D: how good are your object positions? You do not edit this file.

    ros2 run ee414_house_lab l2_check

It asks TF2 where every object_N frame is IN THE WORLD FRAME, and compares
that with where Gazebo really put the cylinders (world_info.CYLINDERS).

It needs a transform world -> odom. Nobody publishes one yet: that is your
job in Task D1. Until you do, this program tells you so and also shows the
comparison done the WRONG way (odom numbers compared with world numbers),
so you can see why the transform is needed.

The table is printed and saved to submission/lab2/lab2_check_<time>.txt.
"""

import datetime
import math
import os
import pathlib
import time

import rclpy
from rclpy.node import Node
from rclpy.parameter import Parameter
from rclpy.time import Time
from tf2_ros import Buffer, TransformListener

from ee414_house_lab import world_info

MAX_OBJECTS = 10


def nearest_cylinder(x, y):
    """(colour, true x, true y, distance) of the true cylinder nearest to (x, y)."""
    best = None
    for colour, (cx, cy) in world_info.CYLINDERS.items():
        d = math.dist((x, y), (cx, cy))
        if best is None or d < best[3]:
            best = (colour, cx, cy, d)
    return best


def lookup_xy(buffer, target, source):
    try:
        t = buffer.lookup_transform(target, source, Time())
        return t.transform.translation.x, t.transform.translation.y
    except Exception:
        return None


def main():
    rclpy.init()
    node = Node('l2_check', parameter_overrides=[Parameter('use_sim_time', value=True)])
    buffer = Buffer()
    TransformListener(buffer, node)

    print('\n  Listening to TF for 3 seconds ...')
    end = time.monotonic() + 3.0
    while time.monotonic() < end:
        rclpy.spin_once(node, timeout_sec=0.1)

    objects = [f'object_{i}' for i in range(MAX_OBJECTS)
               if lookup_xy(buffer, 'odom', f'object_{i}') is not None]
    lines = [f'EE 414 House Lab -- lab 2 check   {datetime.datetime.now():%Y-%m-%d %H:%M:%S}'
             f'   user {os.environ.get("USER", "?")}', '']

    if not objects:
        lines.append('No object_N frames found. Is l2_object_finder running, and has it '
                     'found something?')
    else:
        has_world = lookup_xy(buffer, 'world', 'odom') is not None
        frame = 'world' if has_world else 'odom'
        if not has_world:
            lines += ['!! There is no transform world -> odom yet (Task D1).',
                      '!! Below, your ODOM numbers are compared with WORLD numbers.',
                      '!! Look at the errors: this is what happens without the transform.', '']
        else:
            wo = lookup_xy(buffer, 'world', 'odom')
            lines += [f'world -> odom found: odom origin is at world ({wo[0]:+.2f}, {wo[1]:+.2f})',
                      '']
        lines.append(f'{"frame":10s} {"x (" + frame + ")":>12s} {"y (" + frame + ")":>12s}   '
                     f'{"nearest":8s} {"true x":>8s} {"true y":>8s}   {"error":>7s}')
        lines.append('-' * 78)
        errors = []
        for name in objects:
            x, y = lookup_xy(buffer, frame, name)
            colour, cx, cy, err = nearest_cylinder(x, y)
            errors.append(err)
            lines.append(f'{name:10s} {x:12.3f} {y:12.3f}   {colour:8s} {cx:8.2f} {cy:8.2f}'
                         f'   {err:6.3f} m')
        lines.append('-' * 78)
        lines.append(f'objects: {len(objects)}   mean error: {sum(errors) / len(errors):.3f} m'
                     f'   worst: {max(errors):.3f} m'
                     + ('' if has_world else '   (without world -> odom!)'))
        if has_world:
            ok = sum(1 for e in errors if e < 0.10)
            lines.append(f'objects within 10 cm of the truth: {ok} of {len(objects)}')

    text = '\n'.join(lines) + '\n'
    print('\n' + text)

    base = os.environ.get('EE414_LAB_DIR')
    d = (pathlib.Path(base) / 'submission' if base else pathlib.Path.home() / 'ee414_lab_results') / 'lab2'
    d.mkdir(parents=True, exist_ok=True)
    path = d / f'lab2_check_{datetime.datetime.now():%Y%m%d-%H%M%S}.txt'
    path.write_text(text)
    print(f'  saved: {path}\n')
    node.destroy_node()
    rclpy.try_shutdown()


if __name__ == '__main__':
    main()
